export function Feedback({
  status = "{{status}}",
  message = "{{message}}",
  showIcon = {{showIcon}},
  accent = "{{accent}}",
}) {
  const styles = {
    success: { background: "#A8E6C133", border: "1px solid #A8E6C1" },
    error: { background: "#F5C2E033", border: "1px solid #F5C2E0" },
    neutral: { background: "#24143011", border: "1px solid #24143022" },
  }[status];
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430aa" }}>
      <div role="status" style={{ display: "flex", alignItems: "center", gap: 8, padding: "10px 14px", borderRadius: 8, fontWeight: 600, color: "#241430", ...styles }}>
        {showIcon && <span style={{ width: 8, height: 8, borderRadius: 999, flex: "none", background: accent }} />}
        <span>{message}</span>
      </div>
      <p style={{ margin: "10px 0 0" }}>The system tells the user what happened &mdash; {status} feedback</p>
    </div>
  );
}
